        emoji: '🔊',
        body: `▼ゼロから：
「音が大きい・小さい」を人の感覚そのままで扱うと設計に使えないため、
音響では周波数（音の高さ）と音圧レベル（音の強さ、デシベル）という
物理量に置き換えて考えます。さらに人の聴感に合わせた評価尺度も使います。

━━━━━━━━━━━━━━━━━━━━━━
🔑 周波数と音圧レベル（デシベル）
━━━━━━━━━━━━━━━━━━━━━━
・周波数（Hz）：1秒間の振動回数。高いほど高い音に聞こえる★
・人の可聴域はおおむね20Hz〜20000Hzとされる
・音圧レベル（dB）：基準値に対する音圧の比を対数で表した量★
・デシベルは対数尺度のため、音源が2つに増えても音圧レベルは2倍にはならない★

━━━━━━━━━━━━━━━━━━━━━━
🔑 デシベルの合成は足し算にならない
━━━━━━━━━━━━━━━━━━━━━━
・同じ音圧レベルの音源を2つ合成すると、レベルは約3dB上がる（2倍にはならない）★
・音源からの距離が2倍になると、点音源の音圧レベルは約6dB低下する★
・線音源（道路交通騒音など）は距離が2倍で約3dB低下する傾向がある
・暗騒音より十分低いレベルの音は、全体の騒音レベルにほとんど影響しない

【計算例】音源合成の感覚
　60dBの音源が1つ→60dB
　60dBの音源を2つ同時に鳴らす→約63dB（2倍の120dBにはならない）★
　→ 「音源の数が倍になれば dB も倍になる」は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 NC値と等価騒音レベル
━━━━━━━━━━━━━━━━━━━━━━
・NC値（Noise Criteria）：室内騒音の許容基準を周波数帯域ごとに評価する指標★
・NC値が小さいほど静かな室であることを示す★
・コンサートホールや録音スタジオは特に低いNC値が求められる
・等価騒音レベル（LAeq）：変動する騒音を一定時間で平均化して1つの値で表す指標★
・環境騒音の評価には等価騒音レベルが広く用いられる

【図解】室用途とNC値の目安（低いほど静粛）
　室用途｜求められる静粛性
　放送スタジオ・コンサートホール｜非常に高い（NC値が小さい）★
　会議室・個室事務室｜中程度
　工場・機械室｜低い（NC値が大きくても許容）
　⚠「NC値は大きいほど静かな室を示す」は誤り。小さいほど静か

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・×「音源が2倍になると音圧レベルも2倍になる」→ 約3dB上昇するにすぎない
・×「点音源は距離2倍で音圧レベルが半分になる」→ デシベルは約6dB低下
・○「等価騒音レベルは変動騒音を平均化して評価する」→ 正しい
・○「NC値は周波数帯域ごとの許容値で評価する」→ 正しい

★ここだけ暗記
・デシベルは対数尺度。同レベル音源2つの合成で約3dB上昇（2倍ではない）
・点音源は距離2倍で約6dB低下、線音源は距離2倍で約3dB低下
・NC値は小さいほど静か。等価騒音レベルは変動騒音の平均的評価`,
