        emoji: '🧱',
        body: `▼ゼロから：
隣室の音がうるさい原因は「壁が音を通してしまう（遮音不足）」ことが多く、
室内の反響がうるさい原因は「壁が音を吸収しない（吸音不足）」ことが多い。
この「遮る」と「吸う」はまったく別の性能で、試験でもよく対比されます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 遮音性能（透過損失）の基本
━━━━━━━━━━━━━━━━━━━━━━
・透過損失（TL）：壁体を音がどれだけ透過しにくいかを表す値（dB）★
・透過損失が大きいほど遮音性能が高い（音を通しにくい）★
・質量則：壁体の面密度（単位面積あたり質量）が大きいほど透過損失は増える★
・面密度が2倍になると、透過損失はおおむね6dB程度増加する傾向がある
・壁に隙間があると、その隙間を通じて遮音性能が著しく低下する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 吸音性能（吸音率）の基本
━━━━━━━━━━━━━━━━━━━━━━
・吸音率α：入射した音のエネルギーのうち吸収される割合（0〜1で表す）★
・吸音率が高い材料（グラスウール等の多孔質材料）は高音域の吸音に優れる★
・剛壁（コンクリート等）は吸音率が低く、音をよく反射する
・吸音は「室内の響きを抑える」ためのもので、隣室への音漏れ（遮音）は防げない★
・むしろ剛性が高く重い壁ほど遮音性能は高いが、吸音性能は低い傾向にある

【図解】遮音と吸音の違い
　性能｜目的｜性質の良い材料の傾向
　遮音（透過損失）｜音を室外・隣室に漏らさない｜重く密な材料★
　吸音（吸音率）｜室内の反響・残響を抑える｜軽く多孔質な材料★
　⚠「重い壁は吸音性能も高い」は誤り。遮音性能は高いが吸音性能は低い

━━━━━━━━━━━━━━━━━━━━━━
🔑 床衝撃音（軽量・重量）
━━━━━━━━━━━━━━━━━━━━━━
・軽量床衝撃音：スプーンを落とす等、高周波数域が主体の軽く硬い衝撃音★
・重量床衝撃音：子どもの飛び跳ね等、低周波数域が主体の重く柔らかい衝撃音★
・軽量床衝撃音にはカーペットや緩衝材などの「柔らかい仕上げ」が有効★
・重量床衝撃音には床スラブの質量増加・剛性向上が有効（仕上げ材だけでは効果小）★
・L値（遮音等級）は数値が小さいほど床衝撃音の遮断性能が高いことを示す

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・×「吸音率が高い壁は遮音性能も高い」→ 軽い多孔質材料は遮音性能は低い傾向
・×「カーペットを敷けば重量床衝撃音も軽減できる」→ 軽量衝撃音には有効だが重量には効果小
・○「壁の面密度を上げると透過損失（遮音性能）が向上する」→ 正しい（質量則）
・○「L値は小さいほど床衝撃音の遮断性能が高い」→ 正しい

★ここだけ暗記
・遮音は透過損失（重く密な壁が有利）、吸音は吸音率（軽く多孔質が有利）で別物
・軽量床衝撃音は柔らかい仕上げ材、重量床衝撃音はスラブの質量・剛性で対策
・壁の隙間は遮音性能を大きく損なう弱点になる`,
