        body: `▼ゼロから：
空調で使う冷水・温水はどこかで「つくる」必要があり、その役割を担うのが
熱源機器です。暖房用の熱をつくるボイラー、冷房用の冷熱をつくる冷凍機、
そして両方をこなせるヒートポンプの違いを整理します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ボイラーの種類
━━━━━━━━━━━━━━━━━━━━━━
・炉筒煙管ボイラー：比較的大容量で中規模〜大規模建物に用いられる★
・貫流ボイラー：保有水量が少なく、起動が早い。小型でも設置される★
・真空式・無圧式温水発生機：大気圧以下で運転し、取扱資格が不要な場合が多い
・ボイラーの効率は、排熱回収（エコノマイザ等）の有無で変わる

━━━━━━━━━━━━━━━━━━━━━━
🔑 冷凍機の種類（圧縮式・吸収式）
━━━━━━━━━━━━━━━━━━━━━━
・圧縮式冷凍機：電気で圧縮機を駆動し、冷媒を循環させて冷熱をつくる★
・吸収式冷凍機：主に熱（蒸気・温水・ガス）を駆動源とし、電力消費が少ない★
・吸収式は冷媒に水、吸収剤に臭化リチウム溶液を用いるものが一般的★
・ターボ冷凍機（遠心式）は大容量の圧縮式冷凍機として大規模建物で使われる

━━━━━━━━━━━━━━━━━━━━━━
🔑 ヒートポンプとCOP
━━━━━━━━━━━━━━━━━━━━━━
・ヒートポンプ：冷媒の相変化を利用し、1台で冷房・暖房両方に対応できる機器★
・COP（成績係数）＝得られる熱量（能力）÷投入したエネルギー（消費電力）★
・COPが大きいほど、少ない投入エネルギーで多くの熱を得られる（高効率）★
・空気熱源ヒートポンプは外気温が低いほど暖房能力・COPが低下する傾向がある★
・水熱源・地中熱源は年間を通じた熱源側温度が安定しており効率が安定しやすい

【図解】熱源機器の特徴比較
　機器｜主な駆動源｜特徴
　圧縮式冷凍機｜電力｜高効率だが電力デマンドが大きい
　吸収式冷凍機｜熱（蒸気・ガス等）｜電力消費は少ないがCOPは低め★
　ヒートポンプ｜電力｜1台で冷暖房両用、COPで効率評価★
　⚠「吸収式冷凍機は電力をまったく使わない」は誤り。補機等でわずかに使用する

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・×「COPは小さいほど高効率」→ 大きいほど高効率
・×「吸収式冷凍機は圧縮機で冷媒を圧縮する」→ 熱による吸収・再生サイクルで動作
・○「空気熱源ヒートポンプは外気温が下がると暖房能力が落ちる」→ 正しい
・○「吸収式冷凍機の冷媒には水が用いられることが多い」→ 正しい

★ここだけ暗記
・ボイラー（暖房用）、冷凍機（圧縮式・吸収式、冷房用）、ヒートポンプ（冷暖房兼用）の役割分担
・COP＝得られる熱量÷消費エネルギー。大きいほど高効率
・吸収式は熱駆動で電力消費が少ないがCOPは圧縮式より低め`,
