・構内交換機（PBX）、インターホン設備、監視カメラ等も電気設備計画に含まれる
・防犯設備（入退室管理・監視カメラ等）は用途・セキュリティレベルに応じて計画する★
・テレビ共同受信設備（CATV等）の配線ルートも計画段階で検討する

【図解】建物内の弱電設備の例
　設備｜主な目的
