━━━━━━━━━━━━━━━━━━━━━━
・日射負荷は方位によってピーク時刻が異なる（東面は午前、西面は午後など）★
・建物全体の最大負荷は、各室の最大負荷を単純に合計した値より小さくなることが多い★
