・ペリメーターゾーン：外壁に面し、日射・外気温の影響を強く受ける部分★
・インテリアゾーン：建物内部で外気の影響が少なく、内部発熱が支配的な部分★
・ペリメーターゾーンは季節で暖房・冷房どちらも必要になりやすい（南北の方位差も大）★
・インテリアゾーンは年間を通じ冷房負荷（内部発熱の排熱）が主体になりやすい

