        body: `▼ゼロから：
換気は室内の空気質を保つために必須ですが、暖めた（あるいは冷やした）
空気をそのまま外に捨てて冷たい外気を取り込むと、熱エネルギーの無駄に
なります。この無駄を減らす装置が全熱交換器です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 全熱交換器の仕組み
━━━━━━━━━━━━━━━━━━━━━━
・全熱交換器：排気と給気をすれ違わせ、温度（顕熱）と湿度（潜熱）の両方を
　熱交換素子を介して回収する換気装置★
・顕熱のみを交換する「顕熱交換器」に対し、全熱交換器は湿気も同時に回収する★
・熱交換効率が高いほど、外気負荷（冷暖房負荷）の低減効果が大きい★
・ロータリー式（回転型）とプレート式（固定型）等の方式がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 全熱交換器の効果と留意点
━━━━━━━━━━━━━━━━━━━━━━
・全熱交換器を用いると、換気による熱損失・熱取得を大幅に低減できる★
・冬は排気の暖かさ・湿気を給気に戻し、夏は排気の涼しさ・低湿度を給気に戻す★
・排気と給気の経路が直接混ざらない構造（間接熱交換）とするのが基本★
・フィルターの目詰まり等により熱交換効率が低下するため、定期保守が必要

【図解】顕熱交換器と全熱交換器の違い
　種類｜回収する熱
　顕熱交換器｜温度（顕熱）のみ★
　全熱交換器｜温度（顕熱）＋湿度（潜熱）★
　⚠「全熱交換器は温度のみを回収する」は誤り。湿度（潜熱）も回収する点が特徴

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・×「全熱交換器は給排気を直接混合して熱を回収する」→ 混合せず熱交換素子を介して回収
・×「顕熱交換器は湿度も回収できる」→ 顕熱交換器は温度のみ、全熱交換器が湿度も回収
・○「全熱交換器は外気負荷の低減に有効な省エネ手法である」→ 正しい
・○「熱交換効率はフィルターの汚れ等で低下するため保守が必要」→ 正しい

★ここだけ暗記
・全熱交換器は温度（顕熱）＋湿度（潜熱）を回収、顕熱交換器は温度のみ
・換気による熱損失・熱取得を抑える省エネ設備として外気負荷を低減する`,
