━━━━━━━━━━━━━━━━━━━━━━
・FCU単体では新鮮外気を取り入れられないため、別途外調機（外気処理空調機）が必要★
・各室に機器が分散するため、フィルター清掃等の保守の手間が増える
・2管式・4管式の違いにより、冷房・暖房の同時運転可否が変わる（4管式は同時運転可）★

