━━━━━━━━━━━━━━━━━━━━━━
・圧力タンク方式：密閉タンク内の空気を圧縮し、その圧力で給水する方式。高置水槽が不要★
・ポンプ直送方式：ポンプの運転台数・回転数を制御して直接各階に給水する方式★
・両方式とも停電時は給水が停止するため、非常用電源の有無が重要な検討事項になる
・ポンプ直送方式はインバーター制御との組合せで省エネ性に優れる場合が多い★

【図解】給水方式の比較
