        body: `▼ゼロから：
停電時にも建物の機能を維持するための電源設備には、瞬断を許容する
ものと、瞬断すら許されないものがあります。非常用発電設備とUPSの
役割の違いを理解しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 非常用発電設備
━━━━━━━━━━━━━━━━━━━━━━
・停電時に自動的に起動し、消防用設備等の非常電源として電力を供給する★
・起動までに数秒〜数十秒程度の時間（瞬時の停電）が生じることが一般的
・容量算定には、同時に稼働させる負荷（スプリンクラーポンプ・排煙機等）を積み上げて検討する★
・燃料の種類（軽油・ガス等）や連続運転可能時間も設計上の重要な検討事項

━━━━━━━━━━━━━━━━━━━━━━
🔑 無停電電源装置（UPS）
━━━━━━━━━━━━━━━━━━━━━━
・内蔵バッテリーにより、停電時も瞬断なく電力を供給し続ける装置★
・サーバー室・中央監視室等、瞬断すら許容できない重要負荷に用いられる★
・UPSが供給できる時間は一般に短時間（数分〜数十分程度）であり、長時間は非常用発電設備と併用する
・非常用発電設備の起動までのつなぎとして、UPSを組み合わせる構成もある★

【図解】非常用電源の比較
設備｜瞬断の有無｜供給時間の目安
非常用発電設備｜あり（起動時間）｜比較的長時間★
UPS｜なし（瞬断なし）★｜短時間
⚠ UPSだけでは長時間の停電に対応できないため、重要負荷ほど両者の併用が検討される

★ここだけ暗記
・非常用発電設備は起動に時間を要するが長時間供給可能★
・UPSは瞬断なしだが供給時間は短い、重要負荷では併用する★`,
