        body: `▼ゼロから：
脱炭素化の流れの中で、建築物への太陽光発電設備の導入が増えています。
発電の仕組みと、建築計画上の留意点を押さえておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 太陽光発電の基本原理
━━━━━━━━━━━━━━━━━━━━━━
・太陽電池モジュール（パネル）が光エネルギーを直接電力（直流）に変換する★
・発電した直流電力は、パワーコンディショナ（PCS）で交流に変換してから使用する★
・発電量は日射量・パネルの設置角度・方位・パネル温度等によって変動する
・パネル温度が高くなるほど、一般に発電効率は低下する傾向がある★

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築計画上の留意点
━━━━━━━━━━━━━━━━━━━━━━
・日本国内では、南向き・適切な傾斜角で設置すると年間発電量が大きくなりやすい
・他の建物や設備機器による影（日影）がかかると、発電量が大きく低下することがある★
・系統連系（電力会社の系統につなぐ）する場合は、逆潮流（余剰電力の売電）の扱いも検討事項となる
・自家消費型・売電型など、導入目的によって設計（容量・蓄電池の有無）が変わる

【図解】太陽光発電の構成要素
機器｜役割
太陽電池モジュール｜光→直流電力に変換★
パワーコンディショナ（PCS）｜直流→交流に変換★
⚠ パネルに一部でも影がかかると、その系統全体の発電量が大きく低下することがある

★ここだけ暗記
・太陽電池は光を直流電力に変換し、PCSで交流に変換して利用する★
・影の影響・パネル温度上昇は発電効率低下の要因★`,
