        body: `▼ゼロから：
エレベーターは建物の高さ・用途によって求められる速度や台数が
大きく異なります。超高層ビルの基準階用エレベーターと、低層住宅用の
それとでは設計思想が全く異なることを理解しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 速度区分の考え方
━━━━━━━━━━━━━━━━━━━━━━
・低速エレベーター：中低層建築物向け。速度は比較的遅い★
・高速・超高速エレベーター：超高層建築物の基準階サービス用等に用いられ、分速が非常に大きい★
・速度が速いほど、乗りかごの加減速時の乗り心地（加速度・躍度）への配慮がより重要になる
・ロープ式が一般的だが、低層向けには油圧式が用いられることもある

━━━━━━━━━━━━━━━━━━━━━━
🔑 群管理方式の基礎
━━━━━━━━━━━━━━━━━━━━━━
・複数台のエレベーターを1つのグループとして、呼び登録に対し最適な号機を自動的に割り当てる制御方式★
・朝の出勤時間帯等、特定方向への交通需要が集中する時間帯には、専用の運転モードを設けることがある
・AI等を用いた需要予測により、待ち時間の短縮を図る高度な群管理システムも普及している★

【図解】エレベーターの基本区分
区分｜内容
速度区分｜低速・高速・超高速★
駆動方式｜ロープ式・油圧式
制御方式｜群管理方式（複数台の最適配車）★
⚠ 超高層建築物では、高速エレベーターでも各階停止すると時間がかかるため、ゾーニング計画も重要

★ここだけ暗記
・エレベーターは建物規模・用途に応じ速度区分・駆動方式を選定する★
・群管理方式は複数台を最適配車し待ち時間を短縮する仕組み★`,
