        body: `▼ゼロから：
建築物のエネルギー消費性能を評価する制度では、「どれだけエネルギーを
使うか」を数値化した指標が使われます。その代表がBEI（Building
Energy Index）です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 BEIの考え方
━━━━━━━━━━━━━━━━━━━━━━
・BEI＝設計一次エネルギー消費量／基準一次エネルギー消費量★
・値が1.0未満であれば、基準より省エネ性能が高いことを意味する★
・設計一次エネルギー消費量には、空調・換気・照明・給湯・昇降機等の消費量を合算する
・太陽光発電等による創エネ分は、一次エネルギー消費量から差し引いて評価されることがある★

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築物省エネ法との関係
━━━━━━━━━━━━━━━━━━━━━━
・建築物省エネ法では、一定規模以上の建築物に省エネ基準への適合が義務付けられている★
・外皮性能（断熱等）の基準と、設備を含めた一次エネルギー消費量の基準の両方で評価される
・住宅と非住宅で評価の考え方や指標（外皮性能はUA値等）が異なる場合がある

【図解】省エネ性能評価の主な指標
指標｜意味
BEI｜一次エネルギー消費量の基準に対する比★
UA値｜外皮（壁・窓等）の断熱性能を表す値★
⚠ BEIが1.0をわずかに下回るだけでは「十分に省エネ」とは言えず、より小さい値ほど高性能

★ここだけ暗記
・BEI＝設計値／基準値、1.0未満で基準をクリア、小さいほど高性能★
・創エネ（太陽光発電等）は一次エネルギー消費量から差し引ける★`,
