        emoji: '🏢',
        body: `▼ゼロから：
省エネと創エネを組み合わせて、建物の一次エネルギー消費量を正味
ゼロに近づける考え方がZEBです。達成度に応じていくつかのランクに
分類されています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ZEBのランク区分
━━━━━━━━━━━━━━━━━━━━━━
・ZEB：省エネ・創エネにより、一次エネルギー消費量を正味（ネット）でゼロ以下にした建築物★
・Nearly ZEB：正味で75％以上の削減を実現した建築物（ゼロに近い水準）★
・ZEB Ready：省エネのみで50％以上の削減を実現した建築物（創エネは問わない）★
・ZEB Oriented：延べ面積の大きい建築物向けの区分で、一定の省エネ性能を確保したもの

━━━━━━━━━━━━━━━━━━━━━━
🔑 削減率の計算の考え方
━━━━━━━━━━━━━━━━━━━━━━
・削減率は、基準一次エネルギー消費量に対する実際の消費量の削減割合で評価する★
・ZEB Readyの段階では創エネ（太陽光発電等）を見込まず、純粋な省エネ性能で評価する点に注意★
・ZEB・Nearly ZEBの段階では、太陽光発電等の創エネ分を加味して削減率を計算する

【図解】ZEBのランクと削減率の目安
ランク｜削減率の目安｜創エネの要否
ZEB Ready｜50％以上削減｜不要（省エネのみ）★
Nearly ZEB｜75％以上削減｜必要
ZEB｜100％以上削減（正味ゼロ以下）｜必要★
⚠ 「ZEB Readyは創エネを含めて50％削減すればよい」は誤り。創エネを含めずに50％削減が条件

★ここだけ暗記
・ZEB Readyは省エネのみで50％以上削減、創エネは不問★
・ZEB・Nearly ZEBは創エネも含めて評価する★`,
