        body: `▼ゼロから：
建築物の環境性能を総合的に評価する仕組みとして、日本ではCASBEEや
BELSという制度が使われています。それぞれ評価する範囲が異なる点を
整理しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 CASBEE（建築環境総合性能評価システム）
━━━━━━━━━━━━━━━━━━━━━━
・省エネだけでなく、室内環境・景観への配慮・資源循環性等を含めた総合的な環境性能を評価する★
・「環境品質（Q）」と「環境負荷（L）」の両面から評価し、BEE（環境効率）という指標で格付けする★
・評価結果はSランク（素晴らしい）からCランク（劣る）までのランクで表示される
・自治体によっては、一定規模以上の建築物にCASBEE評価の届出を義務付けている場合がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 BELS（建築物省エネルギー性能表示制度）
━━━━━━━━━━━━━━━━━━━━━━
・主に建築物の一次エネルギー消費性能（省エネ性能）に特化した評価・表示制度★
・星（☆）の数で省エネ性能のレベルを表示し、不動産広告等にも活用される★
・CASBEEが環境性能全般を扱うのに対し、BELSは省エネ性能にフォーカスしている点が異なる

【図解】CASBEEとBELSの違い
制度｜評価範囲
CASBEE｜環境性能全般（省エネ・室内環境・資源循環等）★
BELS｜省エネ性能（一次エネルギー消費性能）に特化★
⚠ 「CASBEEとBELSは同じ内容を評価する制度」は誤り。評価範囲の広さが異なる

★ここだけ暗記
・CASBEEは環境性能を総合評価、BELSは省エネ性能に特化した表示制度★
・CASBEEはBEE（環境効率）で格付け、BELSは星の数で表示★`,
