        emoji: '♾️',
        body: `▼ゼロから：
建物にかかる費用や環境負荷は、建てた瞬間だけで決まるものではなく、
建設から解体までの全期間を通して発生します。この「生涯」を通した
評価の考え方がLCC・LCAです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 LCC（ライフサイクルコスト）
━━━━━━━━━━━━━━━━━━━━━━
・LCCは、企画・設計から建設・運用（維持管理・修繕・光熱費等）・解体までの総費用を指す★
・一般に、建設費（イニシャルコスト）よりも運用期間中の費用（ランニングコスト）のほうが
　長期的には総額として大きくなる場合が多い★
・断熱性能や設備の省エネ性能を高めることは、イニシャルコストを増やす一方でランニングコストを
　抑え、LCC全体では有利になることがある

━━━━━━━━━━━━━━━━━━━━━━
🔑 LCA（ライフサイクルアセスメント）
━━━━━━━━━━━━━━━━━━━━━━
・LCAは、建築物が生涯を通じて環境に与える負荷（CO2排出量等）を評価する手法★
・建設資材の製造段階から、建設・運用・解体・廃棄までの各段階の環境負荷を積算する
・LCCCO2（ライフサイクルCO2）として、生涯のCO2排出量を定量的に評価することもある★

【図解】LCCとLCAの視点
指標｜評価対象
LCC｜生涯にわたる費用（コスト）★
LCA（LCCO2）｜生涯にわたる環境負荷（CO2等）★
⚠ イニシャルコストの安さだけで設備・仕様を選ぶと、LCC全体ではかえって不利になることがある

★ここだけ暗記
・LCCは生涯費用、LCAは生涯環境負荷を評価する考え方★
・運用期間中のランニングコストは、イニシャルコストより総額が大きくなることが多い★`,
