        body: `▼ゼロから：
集合住宅等で「隣の音がうるさい」という問題を防ぐには、壁の遮音性能と
床の衝撃音遮断性能を数値で評価する必要があります。Dr値とL値という
2つの指標の違いを理解しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 遮音等級Dr値（壁・床の空気音遮断性能）
━━━━━━━━━━━━━━━━━━━━━━
・Dr値は、壁等を介した音の透過のしにくさ（空気伝搬音の遮断性能）を表す等級★
・Dr値は数値が大きいほど遮音性能が高い（Dr-40よりDr-50のほうが優れる）★
・主に話し声・テレビの音等、空気中を伝わる音の遮断を評価する指標

━━━━━━━━━━━━━━━━━━━━━━
🔑 床衝撃音等級L値（固体伝搬音）
━━━━━━━━━━━━━━━━━━━━━━
・L値は、床に物を落とす・歩く等の衝撃によって生じる音の伝わりにくさを表す等級★
・L値は数値が小さいほど遮断性能が高い（L-45よりL-40のほうが優れる）★（Dr値と大小の向きが逆）
・重量衝撃音（子供の飛び跳ね等、低い鈍い音）と軽量衝撃音（スプーンを落とす等、高い音）で
　特性が異なり、床仕上げ材の工夫（軽量衝撃音向き）だけでは重量衝撃音を十分に抑えられないことがある★

【図解】Dr値とL値の違い
指標｜対象｜性能が高いほど
Dr値｜空気伝搬音（壁等）★｜数値が大きい★
L値｜固体伝搬音（床衝撃音）★｜数値が小さい★
⚠ 「遮音性能はどちらも数値が大きいほど良い」は誤り。L値は小さいほど良い

★ここだけ暗記
・Dr値は大きいほど、L値は小さいほど遮音性能が高い★
・重量衝撃音対策には床仕上げだけでなく躯体（スラブ厚等）の検討も必要★`,
