        body: `▼ゼロから：
現代のオフィスビルには、電話・LANといった情報通信のための配線や
機器も重要な設備の一つです。将来の用途変更にも対応しやすい計画の
考え方を理解しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 構内情報通信網（LAN）の基本構成
━━━━━━━━━━━━━━━━━━━━━━
・MDF（主配線盤）：建物全体の配線が集約される中心的な設備スペース★
・IDF（中間配線盤）：各階等に設け、MDFから分配された配線をさらに各室へ展開する★
・幹線系配線（MDF〜IDF間）と、水平系配線（IDF〜各端末間）に分けて計画する
・将来の情報化需要の変化に対応できるよう、配線スペースに余裕を持たせることが望ましい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 OAフロアとの関係
━━━━━━━━━━━━━━━━━━━━━━
・OAフロア（二重床）は、LAN配線・電源配線を自由な位置に展開できるようにする仕組み★
・モジュール計画（構造スパン・什器配置の基準寸法）と整合させ、レイアウト変更に対応しやすくする

【図解】情報通信設備の主な構成
設備｜役割
MDF｜建物全体の配線を集約★
IDF｜各階・各区画への配線分配★
⚠ MDF・IDFの設置スペースを軽視すると、将来の情報化機器増設に対応できなくなる

★ここだけ暗記
・MDFは建物全体の配線集約拠点、IDFは各階への分配拠点★
・OAフロアはLAN・電源配線の自由な展開とレイアウト変更への対応を可能にする★`,
