        body: `▼ゼロから：
建物から出る排水は一種類ではありません。トイレからの排水と、
台所・洗面からの排水、雨水を区別して計画することが、衛生上・
排水処理上重要になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 排水の種類区分
━━━━━━━━━━━━━━━━━━━━━━
・汚水：大便器・小便器等からの排水（し尿を含む）★
・雑排水：台所・洗面・浴室等からの、し尿を含まない生活排水★
・雨水：屋根・敷地等に降った雨水の排水★
・特殊排水：厨房の油脂を含む排水、工場排水等、通常の処理では対応できない成分を含む排水★

━━━━━━━━━━━━━━━━━━━━━━
🔑 排水系統の分離・合流
━━━━━━━━━━━━━━━━━━━━━━
・公共下水道が分流式の地域では、汚水・雑排水系統と雨水系統を分けて排水する必要がある★
・合流式の地域では、汚水・雑排水・雨水を同一系統で排水できる場合がある
・厨房排水には、油脂分が下水道管を詰まらせないよう、グリース阻集器（グリストラップ）を設ける★

【図解】排水の種類
種類｜内容
汚水｜し尿を含む排水★
雑排水｜し尿を含まない生活排水★
雨水｜屋根・敷地からの雨水
⚠ 分流式地域で雨水を汚水系統に接続すると、処理場への負荷増大や溢水の原因になる

★ここだけ暗記
・排水は汚水・雑排水・雨水・特殊排水に区分される★
・厨房排水にはグリース阻集器で油脂分を分離する★`,
