━━━━━━━━━━━━━━━━━━━━━━
・UGR（統一グレア評価値）：室内の不快グレアの程度を数値化した指標で、値が大きいほどまぶしい★
・輝度対比：視対象とその周囲との明るさの差が大きいほど、まぶしさ・見えにくさを感じやすい
・対策として、光源の遮光角を確保する、光沢のある仕上げを避ける等の工夫がある★

【図解】グレアの分類
種類｜内容
