━━━━━━━━━━━━━━━━━━━━━━
・演色性は、その光源が物の色をどれだけ自然に（太陽光に近く）見せるかを表す性質★
・平均演色評価数Raは、基準光源を100として物体色の再現性を数値化した指標★
・Raが高いほど、物の色が自然に見える（美術館・店舗等、色の見え方が重要な用途で求められる）★
・演色性と明るさ（照度）は別の性質であり、照度が高くても演色性が低い光源はありうる

